let data=window.HOUSE_HUNT, properties=[], view='all', layout='grid', lastList=[], selected=new Set(), saved={favorites:[],hidden:[]};
try{const s=JSON.parse(localStorage.getItem('house-hunt-v1'));if(s&&Array.isArray(s.favorites)&&Array.isArray(s.hidden)){saved={favorites:s.favorites.map(String),hidden:s.hidden.map(String)};if(Array.isArray(s.compare))selected=new Set(s.compare.map(String).slice(0,4))}}catch{}
