let notes={},meta={};
const cloud=window.HH_CLOUD;
const me=()=>cloud?.who||cloud?.user?.name||'';
function applyRow(row){if(!row||!row.listing_id)return;const id=String(row.listing_id);const inF=saved.favorites.includes(id),inH=saved.hidden.includes(id);if(row.favorite&&!inF)saved.favorites.push(id);if(!row.favorite&&inF)saved.favorites=saved.favorites.filter(x=>x!==id);if(row.hidden&&!inH)saved.hidden.push(id);if(!row.hidden&&inH)saved.hidden=saved.hidden.filter(x=>x!==id);if(row.compare&&!row.hidden){if(selected.has(id)||selected.size<4)selected.add(id)}else selected.delete(id);if(typeof row.note==='string'){if(row.note)notes[id]=row.note;else delete notes[id]}meta[id]={by:row.updated_by||null,at:row.updated_at||null}}
const byUpdated=(a,b)=>Date.parse(a.updated_at||0)-Date.parse(b.updated_at||0);
async function loadCloudState(){const rows=(await cloud.load()).sort(byUpdated);const local={favorites:[...saved.favorites],hidden:[...saved.hidden],compare:[...selected]};saved={favorites:[],hidden:[]};selected=new Set();notes={};meta={};rows.forEach(applyRow);
  // one-time import of what this browser had before the shared table existed
  let migrated=false;try{migrated=localStorage.getItem('house-hunt-migrated-v1')==='1'}catch{}
  if(!migrated){const have=new Set(rows.map(r=>String(r.listing_id)));const toPush=[];for(const id of new Set([...local.favorites,...local.hidden,...local.compare]))if(!have.has(id))toPush.push({listing_id:id,favorite:local.favorites.includes(id),hidden:local.hidden.includes(id),compare:local.compare.includes(id)});if(toPush.length){try{await cloud.setMany(toPush);toPush.forEach(applyRow);toast(`Imported ${toPush.length} saved ${toPush.length===1?'choice':'choices'} from this browser into the shared list.`)}catch(e){console.warn('import failed',e)}}try{localStorage.setItem('house-hunt-migrated-v1','1')}catch{}}
  persist();}
let pendingWrites=0;
function cloudSet(id,patch,onFail){if(!cloud||!cloud.user){onFail?.();return Promise.resolve(false)}pendingWrites++;return cloud.set(id,patch).then(()=>true,e=>{console.warn(e);toast('Could not sync that change — check your connection.');onFail?.();return false}).finally(()=>pendingWrites--)}
const snapshotState=()=>JSON.stringify([saved,[...selected],notes]);
const restoreState=snap=>{const [sv,sel,nt]=JSON.parse(snap);saved=sv;selected=new Set(sel);notes=nt};
/* 7. Re-read the shared table (Realtime does not replay events missed while a phone slept). */
let refreshing=false;
async function refreshCloud(){if(!cloud?.user||refreshing||pendingWrites)return;refreshing=true;try{const rows=(await cloud.load()).sort(byUpdated);const before=snapshotState();saved={favorites:[],hidden:[]};selected=new Set();notes={};meta={};rows.forEach(applyRow);if(snapshotState()!==before){persist();configureNeighborhoods();render();renderStats();syncOpenNote()}}catch(e){console.warn('refresh failed',e)}finally{refreshing=false}}
/* keep an open detail modal's note in step with the shared table */
function syncOpenNote(id){const box=$('#modalContent .note-box');if(!box||!$('#modal').open||(id&&box.dataset.id!==String(id)))return;const f=box.querySelector('#noteField'),nid=box.dataset.id;if(document.activeElement!==f)f.value=notes[nid]||'';box.querySelector('#noteStatus').textContent=meta[nid]?.by&&notes[nid]?`Last edited by ${meta[nid].by}`:'Visible to both of you'}
function startLiveSync(){cloud.onChange((row,type)=>{if(!row)return;const id=String(row.listing_id),was={fav:saved.favorites.includes(id),hid:saved.hidden.includes(id),note:notes[id]||'',cmp:selected.has(id)};const before=JSON.stringify([saved,[...selected],notes[id]||'']);applyRow(type==='DELETE'?{listing_id:row.listing_id,favorite:false,hidden:false,compare:false,note:''}:row);const after=JSON.stringify([saved,[...selected],notes[row.listing_id]||'']);if(before===after)return;persist();render();configureNeighborhoods();renderStats();const by=row.updated_by;if(by&&by!==me()){const p=properties.find(x=>idsOf(x).includes(String(row.listing_id)));const now={fav:saved.favorites.includes(id),hid:saved.hidden.includes(id),note:notes[id]||'',cmp:selected.has(id)};const what=now.hid!==was.hid?(now.hid?'hid':'restored'):now.fav!==was.fav?(now.fav?'saved':'unsaved'):now.note!==was.note?(now.note?'left a note on':'cleared the note on'):now.cmp!==was.cmp?(now.cmp?'added to compare':'removed from compare'):'updated';syncOpenNote(id);toast(`${by} ${what} ${p?p.neighborhood+' · '+p.price.toLocaleString('en-US')+' ₾':'a listing'}.`)}});cloud.subscribe()}
function safeUrl(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:'#'}catch{return '#'}}
function imageUrl(url){return /^data\/images\/[\w.-]+$/.test(url||'')?url:safeUrl(url)}
const floor=p=>p.floor===null?unknown:`${p.floor} / ${p.total_floors??'?'}`;
const date=p=>p.listing_date?new Date(p.listing_date).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Tbilisi'}):unknown;
function facts(p){const good=[],bad=[...(p.considerations||[])];if(p.condition==='Newly renovated')good.push('Newly renovated (listing states)');if(p.furniture===true)good.push('Furniture included (listing states)');if(p.heating)good.push(p.heating);if(p.parking)good.push(p.parking);if(p.balcony)good.push('Balcony listed');if(p.price<900)good.push(`${money(1000-p.price)} below your maximum`);if(p.advance_months)bad.push(`${p.advance_months} months’ rent payable in advance (listing states)`);if(p.floor===1)bad.push('First floor — consider privacy when viewing');if(p.floor===p.total_floors)bad.push('Top floor — check roof condition when viewing');if(p.original_currency==='USD')bad.push('USD asking rent: GEL equivalent may change');const ch=priceChange(p);if(ch&&ch.delta<0)good.push(`Price reduced by ${money(-ch.delta)} (was ${money(ch.from)})`);if(ch&&ch.delta>0)bad.push(`Price increased by ${money(ch.delta)} (was ${money(ch.from)})`);if(isSuspect(p))bad.push('Rent per m² far below the snapshot median — verify price and currency');return {good,bad}}
/* ── Listing history: "New" and price-change markers ──────────
   Uses history.json from the Action (serverHistory), else a scraper-provided p.price_history. */
try{localStorage.removeItem('house-hunt-prices-v1')}catch{} // old browser-side price cache, no longer used
const priceHistoryOf=p=>{const pts=idsOf(p).flatMap(id=>serverHistory[id]?.prices||[]).map(x=>({at:x.at,price:Number(x.price)})).filter(x=>Number.isFinite(x.price)&&Number.isFinite(Date.parse(x.at))).sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));const h=pts.filter((x,i)=>!i||x.price!==pts[i-1].price);if(h.length){if(h[h.length-1].price!==p.price)h.push({at:refAt(p)||new Date().toISOString(),price:p.price});return h}if(Array.isArray(p.price_history)&&p.price_history.length)return p.price_history.map(x=>({at:x.at||x.date,price:Number(x.price)})).filter(x=>Number.isFinite(x.price));return []};
/* Earliest date we can trust for a flat: the Action's first_seen, the scraper's first_seen_at, or the
   source's own publish date (published_at) — across every re-posted copy. */
const firstSeenOf=p=>{let best=null;const consider=v=>{if(v&&Number.isFinite(Date.parse(v))&&(!best||Date.parse(v)<Date.parse(best)))best=v};for(const id of idsOf(p)){consider(serverHistory[id]?.first_seen);const copy=id===p.id?p:(p.reposts||[]).find(r=>r.id===id);consider(copy?.first_seen_at);consider(copy?.published_at)}return best};
const refAt=p=>(sourceOf(p)==='ss.ge'&&ssData?.retrieved_at)||(sourceOf(p)==='korter.ge'&&korterData?.retrieved_at)||data?.retrieved_at||null;
const daysOnMarket=p=>{const f=Date.parse(firstSeenOf(p)),ref=Date.parse(refAt(p));return Number.isFinite(f)&&Number.isFinite(ref)?Math.max(0,Math.floor((ref-f)/86400000)):null};
const priceCuts=p=>{const h=priceHistoryOf(p);let n=0;for(let i=1;i<h.length;i++)if(h[i].price<h[i-1].price)n++;return n};
function priceChange(p){const h=priceHistoryOf(p);if(h.length<2)return null;const prev=h[h.length-2],cur=h[h.length-1];if(cur.price!==p.price)return null;return {delta:p.price-prev.price,from:prev.price,since:cur.at,first:h[0].price}}
const shortDate=iso=>iso?new Date(iso).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Tbilisi'}):'';
const NEW_WINDOW_H=24;
function isNew(p){const fs=firstSeenOf(p);if(!fs||!refAt(p))return false;const seen=Date.parse(fs),ref=Date.parse(refAt(p));return Number.isFinite(seen)&&Number.isFinite(ref)&&ref-seen<NEW_WINDOW_H*3600*1000}
/* ── Distance from home ───────────────────────────────────────
   41°46'14.3"N 44°47'35.1"E → 41.770639, 44.793083 */
const HOME={lat:41.770639,lng:44.793083,label:"Aslani's home",labelKa:'ასლანის სახლი'};
let geo={};
const coordsOf=p=>{const g=geo[p.id];if(Number.isFinite(p.lat)&&Number.isFinite(p.lng))return {lat:p.lat,lng:p.lng};if(g&&Number.isFinite(g.lat)&&Number.isFinite(g.lng))return g;return null};
function haversineKm(a,b){const R=6371,toR=x=>x*Math.PI/180,dLat=toR(b.lat-a.lat),dLng=toR(b.lng-a.lng),h=Math.sin(dLat/2)**2+Math.cos(toR(a.lat))*Math.cos(toR(b.lat))*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
