function excludedCard(e){const img=e.image&&imageUrl(e.image)!=='#'?`<img src="${esc(imageUrl(e.image))}" alt="" loading="lazy">`:'';return `<article class="card excluded-card"><a class="ex-photo" href="${esc(safeUrl(e.url))}" target="_blank" rel="noopener noreferrer">${img||'<span>No photo</span>'}</a><div class="card-body"><div class="card-title"><h2>${esc(e.neighborhood||e.district||'Listing '+e.id)}</h2>${e.district?`<span class="district">${esc(e.district)}</span>`:''}</div>${e.address?`<p class="address">${esc(e.address)}</p>`:''}<ul class="specs">${Number.isFinite(e.price)?`<li><b>${e.price.toLocaleString('en-US')}</b> ₾</li>`:''}${e.size?`<li><b>${esc(e.size)}</b> m²</li>`:''}${e.rooms?`<li><b>${esc(e.rooms)}</b> ${e.rooms===1?'room':'rooms'}</li>`:''}${e.floor!=null?`<li><b>${esc(e.floor)}${e.total_floors?' / '+esc(e.total_floors):''}</b> floor</li>`:''}</ul><p class="ex-reason">⛔ ${esc(e.reason)}${e.condition?` <small>· listed condition: ${esc(e.condition)}</small>`:''}</p><div class="card-meta"><span>excluded ${esc(shortDate(e.excluded_at))}${e.last_seen_at&&e.last_seen_at!==e.excluded_at?` · still listed ${esc(shortDate(e.last_seen_at))}`:''}</span><a href="${esc(safeUrl(e.url))}" target="_blank" rel="noopener noreferrer">Open on myhome.ge ↗</a></div></div></article>`}
