const fmtGel=(n,cur='GEL')=>`${Math.round(n).toLocaleString('en-US')} ${cur==='GEL'?'₾':cur}`;
const dmy=d=>d?new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Tbilisi'}):'';
const dmyt=d=>d?new Date(d).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tbilisi'}):'';
function priceChart(checks,cur){if(checks.length<2)return `<p class="flight-note">Price history builds up with every run (${checks.length} point so far).</p>`;const W=640,H=180,P={l:48,r:12,t:14,b:26};const xs=checks.map(c=>Date.parse(c.at)),ys=checks.map(c=>c.price);const x0=Math.min(...xs),x1=Math.max(...xs),lo=Math.min(...ys),hi=Math.max(...ys),pad=Math.max(10,(hi-lo)*.15);const y0=lo-pad,y1=hi+pad;const X=t=>P.l+(x1===x0?0.5:(t-x0)/(x1-x0))*(W-P.l-P.r),Y=v=>H-P.b-(v-y0)/(y1-y0)*(H-P.t-P.b);const pts=checks.map((c,i)=>[X(xs[i]),Y(ys[i])]);const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');const ticks=[lo,hi].concat(lo!==hi?[(lo+hi)/2]:[]);return `<div class="spark-wrap"><svg class="spark" viewBox="0 0 ${W} ${H}" role="img" aria-label="Price over time, ${checks.length} checks from ${dmy(checks[0].at)} to ${dmy(checks[checks.length-1].at)}">${ticks.map(v=>`<g><line x1="${P.l}" x2="${W-P.r}" y1="${Y(v).toFixed(1)}" y2="${Y(v).toFixed(1)}" class="grid"/><text x="${P.l-6}" y="${(Y(v)+4).toFixed(1)}" text-anchor="end" class="tick">${Math.round(v)}</text></g>`).join('')}<text x="${P.l}" y="${H-6}" class="tick">${dmy(checks[0].at)}</text><text x="${W-P.r}" y="${H-6}" text-anchor="end" class="tick">${dmy(checks[checks.length-1].at)}</text><path d="${d}" class="line"/>${pts.map((p,i)=>`<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="4" class="dot" data-i="${i}"><title>${fmtGel(ys[i],cur)} · ${dmyt(checks[i].at)}</title></circle>`).join('')}<line class="xhair off" x1="0" x2="0" y1="${P.t}" y2="${H-P.b}"/></svg><div class="spark-tip" hidden></div></div>`}
function flightCard(r){const cur=r.currency||'GEL',L=r.latest,prev=r.checks?.length>1?r.checks[r.checks.length-2]:null;const days=Math.ceil((Date.parse(r.depart)-Date.now())/86400000);const delta=L&&prev&&prev.price!==L.price?`<em class="delta ${L.price<prev.price?'down':'up'}">${L.price<prev.price?'↓':'↑'} ${fmtGel(Math.abs(L.price-prev.price),cur)}</em>`:'';const stops=L?((L.transfers||0)+(L.return_transfers||0)?`${(L.transfers||0)+(L.return_transfers||0)} stop${(L.transfers||0)+(L.return_transfers||0)>1?'s':''} in total`:'direct both ways'):'';const nearby=(r.nearby||[]).slice(0,10);return `<article class="flight-card" data-route="${esc(r.id)}"><div class="flight-head"><div><p class="eyebrow">✈ ${esc(r.from)} → ${esc(r.to)}</p><h2>${esc(r.label)}</h2><p class="flight-dates">${dmy(r.depart)} → ${dmy(r.return)} · ${Math.round((Date.parse(r.return)-Date.parse(r.depart))/86400000)} nights · ${days>0?`in ${days} days`:days===0?'today':'past'}</p></div><div class="flight-hero">${L?`<strong>${fmtGel(L.price,cur)}</strong>${delta}<small>round trip · 1 adult${L.airline?` · ${esc(L.airline_name||r.airline_names?.[L.airline]||L.airline)}`:''} · ${stops}</small><small class="flight-src">${L.source==='google'?'live fare via Google Flights':'cached fare via Aviasales'}${r.google?.price&&L.source!=='google'?` · Google: ${fmtGel(r.google.price,cur)}`:''}${r.aviasales?.price&&L.source==='google'&&r.aviasales.price!==L.price?` · Aviasales cache: ${fmtGel(r.aviasales.price,cur)}`:''}</small>`:`<strong>—</strong><small>${r.unavailable_since?'No cached fare for these dates right now':'Not checked yet'}</small>`}</div></div><div class="flight-stats">${r.min!=null?`<span>Lowest seen <b>${fmtGel(r.min,cur)}</b></span><span>Highest <b>${fmtGel(r.max,cur)}</b></span>`:''}<span>Checked <b>${dmyt(r.checked_at)}</b></span>${r.changed_at?`<span>Last change <b>${dmyt(r.changed_at)}</b></span>`:''}</div>${priceChart(r.checks||[],cur)}<div class="detail-links"><a href="${esc(safeUrl(r.booking_url||'#'))}" target="_blank" rel="noopener noreferrer">Book on Wizz Air ↗</a>${r.google?.url?`<a href="${esc(safeUrl(r.google.url))}" target="_blank" rel="noopener noreferrer">Google Flights ↗</a>`:''}${r.aviasales?.link?`<a href="${esc(safeUrl(r.aviasales.link))}" target="_blank" rel="noopener noreferrer">Aviasales ↗</a>`:''}</div>${nearby.length?`<h3>Cheaper nearby dates <small>${r.min_nights||3}–${r.max_nights||14} nights, same months</small></h3><div class="table-wrap"><table class="flight-table"><thead><tr><th>Out</th><th>Back</th><th>Nights</th><th>Price</th><th>vs. your dates</th><th></th></tr></thead><tbody>${nearby.map(n=>{const same=n.departure_at.slice(0,10)===r.depart&&n.return_at.slice(0,10)===r.return;const diff=L?n.price-L.price:null;return `<tr class="${same?'is-you':''}"><td>${dmy(n.departure_at)}</td><td>${dmy(n.return_at)}</td><td>${n.nights}</td><td><b>${fmtGel(n.price,cur)}</b></td><td>${same?'your dates':diff===null?'':diff<0?`<em class="delta down">↓ ${fmtGel(-diff,cur)}</em>`:diff>0?`<em class="delta up">↑ ${fmtGel(diff,cur)}</em>`:'same'}</td><td>${n.link?`<a href="${esc(safeUrl(n.link))}" target="_blank" rel="noopener noreferrer">open ↗</a>`:''}</td></tr>`}).join('')}</tbody></table></div>`:''}<p class="data-note">The headline fare is Google Flights' live price (it asks Wizz Air directly); Aviasales' cached prices fill in when Google is unavailable and power the nearby-dates table. Per adult, round trip; the booking site is the source of truth.</p></article>`}
function renderFlights(){const routes=Object.values(flightsData?.routes||{});$('#grid').innerHTML=routes.length?`<div class="flights">${routes.map(flightCard).join('')}</div>`:'<div class="empty"><h2>No flight data yet.</h2><p>The Action records fares after its next run (needs the TRAVELPAYOUTS_TOKEN secret).</p></div>';$('#resultCount').textContent=routes.length?`${routes.length} ${routes.length===1?'route':'routes'}`:'';}
$('#grid').addEventListener('mousemove',e=>{const svg=e.target.closest('svg.spark');if(!svg)return;const wrap=svg.parentElement,tip=wrap.querySelector('.spark-tip'),dots=[...svg.querySelectorAll('.dot')];if(!dots.length)return;const r=svg.getBoundingClientRect(),sx=640/r.width,mx=(e.clientX-r.left)*sx;let best=dots[0],bd=1e9;for(const d of dots){const dx=Math.abs(Number(d.getAttribute('cx'))-mx);if(dx<bd){bd=dx;best=d}}dots.forEach(d=>d.classList.toggle('on',d===best));const xh=svg.querySelector('.xhair');xh.classList.remove('off');xh.setAttribute('x1',best.getAttribute('cx'));xh.setAttribute('x2',best.getAttribute('cx'));tip.hidden=false;tip.textContent=best.querySelector('title').textContent;const left=Number(best.getAttribute('cx'))/sx;tip.style.left=Math.min(Math.max(left,60),r.width-60)+'px'});
