let commute={};
async function loadCommute(){if(location.protocol==='file:')return;for(const url of ['data/commute.json?t='+Date.now(),liveUrl('commute.json')+'?t='+Date.now()]){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)continue;const j=await r.json();if(j&&j.listings&&typeof j.listings==='object'&&Object.keys(j.listings).length>Object.keys(commute).length)commute=j.listings}catch{}}}
const driveMin=p=>{for(const id of idsOf(p)){const c=commute[id];if(c&&Number.isFinite(c.drive_min))return c.drive_min}return null};
const fmtDrive=m=>m===null?null:m<60?`${m} min`:`${Math.floor(m/60)} h ${m%60} min`;
const GEO_REMOTE=liveUrl('geo.json');
async function loadGeo(){if(location.protocol==='file:')return;const merged={};for(const url of ['data/geo.json?t='+Date.now(),GEO_REMOTE&&GEO_REMOTE+'?t='+Date.now()].filter(Boolean)){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)continue;const j=await r.json();if(j&&j.listings&&typeof j.listings==='object')Object.assign(merged,j.listings)}catch{}}if(Object.keys(merged).length)geo=merged}
let valueCut=Infinity,suspectCut=0,areaMedians={};
const areaMedian=p=>{const nb=areaMedians['nb:'+nbKey(p.neighborhood)];if(nb)return {label:p.neighborhood,median:nb};const d=areaMedians['d:'+p.district];return d?{label:p.district,median:d}:null};
const vsArea=p=>{const m=areaMedian(p);if(!m)return null;return {pct:Math.round((p.price/p.size/m.median-1)*100),label:m.label}};
const medianOf=a=>{const r=[...a].sort((x,y)=>x-y),m=Math.floor(r.length/2);return r.length?(r.length%2?r[m]:(r[m-1]+r[m])/2):0};
const isSuspect=p=>suspectCut>0&&p.price/p.size<suspectCut;
const ppm=p=>Math.round(p.price/p.size);
