function popupHtml(p){const c=coordsOf(p),d=fmtKm(distanceKm(p)),fav=isFav(p);return `<div class="map-card" data-id="${esc(p.id)}"><button class="map-photo" data-action="details" aria-label="View ${esc(p.address)}">${p.main_image&&imageUrl(p.main_image)!=='#'?`<img src="${esc(imageUrl(p.main_image))}" alt="" loading="lazy">`:''}</button><div class="map-body"><div class="map-price">${p.price.toLocaleString('en-US')} ₾ <small>/ month</small></div><div class="map-title">${esc(p.neighborhood)} <span>· ${esc(p.district)} · ${esc(sourceOf(p))}</span></div><div class="map-addr">${esc(p.address||unknown)}</div><div class="map-specs">${p.size} m² · ${esc(value(p.rooms))} ${p.rooms===1?'room':'rooms'} · floor ${esc(floor(p))}${d?` · <b>${d}</b>${driveMin(p)!==null?` · 🚗 ${fmtDrive(driveMin(p))}`:''} from home`:''}</div><div class="map-actions"><button class="primary" data-action="details">Details</button><button data-action="favorite" aria-pressed="${fav}">${fav?'♥ Saved':'♡ Favorite'}</button><a href="${esc(directionsUrl(p)||'#')}" target="_blank" rel="noopener noreferrer">Directions ↗</a></div></div></div>`}
async function renderMap(list){try{await ensureLeaflet()}catch{$('#mapNote').textContent='The map library could not be loaded. Check your connection and try again.';return}
if(!map){map=L.map('map',{scrollWheelZoom:true,zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);L.marker([HOME.lat,HOME.lng],{icon:L.divIcon({className:'pin-wrap',html:`<span class="pin pin-home" title="${esc(HOME.label)}">⌂ ${esc(HOME.label)}</span>`,iconSize:[0,0],iconAnchor:[0,0]}),zIndexOffset:1000,interactive:false}).addTo(map);[2,4,7].forEach(km=>L.circle([HOME.lat,HOME.lng],{radius:km*1000,color:'#2c7a5c',weight:1,opacity:.35,fill:false,dashArray:'4 6',interactive:false}).addTo(map));markerLayer=L.layerGroup().addTo(map);map.on('popupopen',e=>{openPopupId=e.popup._source?.__id||null});map.on('popupclose',()=>{openPopupId=null})}
const wanted=openPopupId;markerLayer.clearLayers();const pts=[];let reopen=null;let missing=0;for(const p of list){const c=coordsOf(p);if(!c){missing++;continue}const m=L.marker([c.lat,c.lng],{icon:L.divIcon({className:'pin-wrap',html:`<span class="pin ${pinClass(p)}">${p.price.toLocaleString('en-US')} ₾</span>`,iconSize:[0,0],iconAnchor:[0,0]}),riseOnHover:true});m.__id=p.id;m.bindPopup(()=>popupHtml(p),{maxWidth:300,minWidth:260,closeButton:true,autoPanPadding:[24,24]});if(wanted===p.id)reopen=m;markerLayer.addLayer(m);pts.push([c.lat,c.lng])}
$('#mapNote').textContent=[`${pts.length} ${pts.length===1?'home':'homes'} on the map`,missing?`${missing} without coordinates`:'',`dashed rings: 2 / 4 / 7 km from ${HOME.label}`].filter(Boolean).join(' · ');
requestAnimationFrame(()=>{map.invalidateSize();if(reopen)reopen.openPopup();if(!mapFitted&&pts.length){const near=pts.filter(([la,ln])=>haversineKm(HOME,{lat:la,lng:ln})<=8);map.fitBounds(L.latLngBounds([...(near.length?near:pts),[HOME.lat,HOME.lng]]).pad(.12),{maxZoom:14});mapFitted=true}else if(!pts.length){map.setView([HOME.lat,HOME.lng],13)}})}
try{const l=localStorage.getItem('house-hunt-layout');if(l==='map'||l==='grid')layout=l}catch{}
window.addEventListener('resize',()=>{if(map&&layout==='map')map.invalidateSize()});
(async()=>{if(cloud){try{await cloud.ready;await loadCloudState();startLiveSync();window.addEventListener('hh-realtime',e=>{if(e.detail!=='SUBSCRIBED')toast('Live updates unavailable — the shared list refreshes every 5 minutes instead.')},{once:true});cloud.onWho(name=>toast(`You are now ${name}.`))}catch(e){console.warn('cloud unavailable',e);toast('Shared list unavailable right now — showing this browser\'s copy.')}}await init()})();

/* ── Visual layer: stats, reveal, spotlight, progress ─────────── */
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
function countTo(el,target,fmt=v=>Math.round(v).toLocaleString('en-US')){const from=Number(el.dataset.current||0);if(reduceMotion||from===target){el.textContent=fmt(target);el.dataset.current=target;return}const t0=performance.now(),dur=1100;const step=now=>{const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,3);el.textContent=fmt(from+(target-from)*e);if(k<1)requestAnimationFrame(step);else el.dataset.current=target};requestAnimationFrame(step)}
function renderStats(){const live=properties.filter(p=>!isHidden(p));if(!live.length){document.querySelectorAll('[data-stat]').forEach(el=>countTo(el,0));return}const prices=live.map(p=>p.price).sort((a,b)=>a-b),mid=Math.floor(prices.length/2),median=prices.length%2?prices[mid]:(prices[mid-1]+prices[mid])/2;const avgSize=live.reduce((a,p)=>a+p.size,0)/live.length;const medPpm=medianOf(live.map(p=>p.price/p.size));const map={count:live.length,median,size:avgSize,ppm:medPpm};document.querySelectorAll('[data-stat]').forEach(el=>countTo(el,map[el.dataset.stat]))}
const revealObserver='IntersectionObserver'in window?new IntersectionObserver(entries=>{entries.filter(e=>e.isIntersecting).forEach((e,k)=>{e.target.style.setProperty('--i',Math.min(k,5));e.target.classList.add('in');revealObserver.unobserve(e.target)})},{rootMargin:'0px 0px 25% 0px',threshold:0}):null;
function revealCards(){const cards=document.querySelectorAll('.card:not(.in)');if(!revealObserver||reduceMotion){cards.forEach(c=>c.classList.add('in'));return}cards.forEach(c=>revealObserver.observe(c))}
$('#grid').addEventListener('pointermove',e=>{const c=e.target.closest('.card');if(!c)return;const r=c.getBoundingClientRect();c.style.setProperty('--mx',`${e.clientX-r.left}px`);c.style.setProperty('--my',`${e.clientY-r.top}px`);if(e.pointerType!=='mouse')return;const t=e.target.closest('.track');if(!t)return;const n=Number(t.dataset.n)||1;if(n<2)return;const tr=t.getBoundingClientRect();const idx=Math.max(0,Math.min(n-1,Math.floor((e.clientX-tr.left)/tr.width*n)));if(idx!==Math.round(t.scrollLeft/t.clientWidth)){loadTrack(t);t.scrollTo({left:idx*t.clientWidth,behavior:'auto'})}});
/* ── Card gallery: lazy strip, hover-scrub (mouse), swipe (touch) ── */
function loadTrack(t){if(!t||t.dataset.loaded)return;t.dataset.loaded='1';t.querySelectorAll('img[data-src]').forEach(img=>{img.src=img.dataset.src;img.removeAttribute('data-src');img.onerror=()=>img.remove();if(img.complete&&img.naturalWidth)img.classList.add('loaded');else img.onload=()=>img.classList.add('loaded')})}
$('#grid').addEventListener('pointerover',e=>{const t=e.target.closest('.track');if(t)loadTrack(t)});
$('#grid').addEventListener('touchstart',e=>{const t=e.target.closest('.track');if(t)loadTrack(t)},{passive:true});
$('#grid').addEventListener('scroll',e=>{const t=e.target;if(!t.classList||!t.classList.contains('track'))return;const idx=Math.round(t.scrollLeft/t.clientWidth),wrap=t.parentElement;wrap.querySelectorAll('.dots i').forEach((d,i)=>d.classList.toggle('on',i===idx));const c=wrap.querySelector('.counter');if(c)c.textContent=`${idx+1} / ${t.dataset.n}`},true);
$('#grid').addEventListener('keydown',e=>{const t=e.target.closest('.track');if(!t)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();t.click()}else if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();loadTrack(t);t.scrollBy({left:(e.key==='ArrowRight'?1:-1)*t.clientWidth,behavior:'smooth'})}});
const progressBar=document.querySelector('.progress');
window.addEventListener('scroll',()=>{const y=window.scrollY;document.body.classList.toggle('scrolled',y>40);if(progressBar){const h=document.documentElement.scrollHeight-innerHeight;progressBar.style.transform=`scaleX(${h>0?y/h:0})`}},{passive:true});
if(location.protocol==='https:'||location.protocol==='http:'){
  setInterval(checkForUpdates,5*60*1000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkForUpdates()});
}

